args.sparql:
SELECT ?mother ?motherLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Countess_Johanna_Magdalene_of_Hanau-Lichtenberg dbp:mother ?mother .
  ?mother dbo:birthPlace ?birthPlace .
  OPTIONAL { ?mother rdfs:label ?motherLabel FILTER (lang(?motherLabel) = 'en') }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER (lang(?birthPlaceLabel) = 'en') }
}

